    18	  canActivate() {
    19	    const authData = this.mainDataService.getAuthData();
    20	
    21	    // token lost
    22	    if (!authData) {
    23	      return this.router.createUrlTree(['/r/login', '']);
    24	    }
    25	
    26	    // at least one booklet has a entry code
    27	    if (authData.flags.indexOf('codeRequired') >= 0) {
    28	      return this.router.createUrlTree(['/r/code-input']);
    29	    }
    30	
    31	    // if the user logs in via DirectLoginActivateGuard, the test starts directly without /starter
    32	    if (
    33	      authData.claims &&
    34	      Object.keys(authData.claims).length === 1 &&
    35	      authData.claims.test &&
    36	      authData.claims.test.length === 1 &&
    37	      this.router.getCurrentNavigation()?.previousNavigation === null
    38	    ) {
    39	      return this.backendService.startTest(authData.claims.test[0].id)
    40	        .pipe(map(testId => this.router.createUrlTree(['/t', testId])));
    41	    }
    42	
    43	    // if the user logs in via DirectLoginActivateGuard, the sys-check starts directly without /starter
    44	    if (
    45	      authData.claims &&
    46	      Object.keys(authData.claims).length === 1 &&
    47	      authData.claims.sysCheck &&
    48	      authData.claims.sysCheck.length === 1 &&
    49	      this.router.getCurrentNavigation()?.previousNavigation === null
    50	    ) {
    51	      return this.router.createUrlTree([
    52	        '/check',
    53	        authData.claims.sysCheck[0].workspaceId,
    54	        authData.claims.sysCheck[0].id
    55	      ]);
    56	    }
    57	
    58	    // default case: Login with name, password but no code
    59	    // RedirectCommand is necessary as we want to maintain context of type NavigationBehaviorOptions, which createURLTree()
    60	    // does not take in; it only uses UrlCreationOptions
    61	    return new RedirectCommand(
    62	      this.router.createUrlTree(['/r/starter']),
    63	      this.router.getCurrentNavigation()?.extras
    64	    );
    65	  }
    66	}
